<section class="comm-card"><div class="comm-head"><div><h2>My workflows</h2><p class="muted">Switch workflows on or off and check the latest result.</p></div><input type="search" id="comm-workflow-search" placeholder="Search workflows" style="max-width:230px" aria-label="Search workflows"></div><div class="comm-toolbar" aria-label="Filter workflows"><button class="active" type="button" data-workflow-filter="all">All workflows</button><button type="button" data-workflow-filter="on">On</button><button type="button" data-workflow-filter="off">Off</button></div><div class="comm-scroll"><table class="comm-table" id="comm-workflow-table"><thead><tr><th>On / off</th><th>Workflow</th><th>Channel</th><th>Schedule</th><th>Credit cap</th><th>Next run (UTC)</th><th>Latest result</th><th>Manage slot</th></tr></thead><tbody><?php foreach($automations as $a): ?><tr data-enabled="<?= $a['enabled']?'on':'off'; ?>"><td><?= form_open('communications/automation'); ?><input type="hidden" name="id" value="<?= (int)$a['id']; ?>"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><input name="enabled" value="1" type="checkbox" class="switch" <?= $a['enabled']?'checked':''; ?> onchange="this.form.submit()" aria-label="Enable <?= $h($a['name']); ?>"><?= form_close(); ?></td><td class="wrap"><b><?= $h($a['name']); ?></b><br><span class="muted"><?= $h($segments[$a['segment_key']][0]??$a['segment_key']); ?></span></td><td><?= $h(strtoupper($a['channel'])); ?></td><td>Every <?= (int)$a['interval_days']; ?> days</td><td><?= number_format($a['budget_units']); ?> credits</td><td><?= $h($a['next_run_at']); ?></td><td class="wrap <?= $a['last_error']?'error':''; ?>"><?= $status_text($a['last_error']?:($a['last_run_at']?'Queued '.$a['last_run_at']:'Not run yet')); ?></td><td><?= form_open('communications/automation'); ?><input type="hidden" name="id" value="<?= (int)$a['id']; ?>"><input type="hidden" name="operation" value="archive"><input type="hidden" name="screen" value="<?= $mobile?'mobile':'desktop'; ?>"><button class="btn secondary">Archive &amp; free slot</button><?= form_close(); ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$automations): ?><p class="empty">No workflows yet. Start with a follow-up recipe or create your own.</p><?php endif; ?></section>
